'use client'
import { useRef } from 'react'
import { cn, useSignal, useSignalEffect, useSignals } from '@cascivo/core'
import { builtin, t } from '@cascivo/i18n'
import { VisuallyHidden } from '../visually-hidden/visually-hidden'
import styles from './terminal.module.css'

export type TerminalLineType = 'command' | 'output' | 'error' | 'comment'

export interface TerminalLine {
  text: string
  prefix?: string
  type?: TerminalLineType
}

export interface TerminalProps {
  lines: TerminalLine[]
  /**
   * Characters typed per animation frame.
   *
   * @defaultValue `3`
   * @see the component manifest
   */
  speed?: number
  /**
   * Restart from the first line after the last one.
   *
   * @defaultValue `false`
   * @see the component manifest
   */
  loop?: boolean
  onComplete?: () => void
  labels?: { label?: string }
  className?: string
}

export function Terminal({
  lines,
  speed = 3,
  loop = false,
  onComplete,
  labels,
  className,
}: TerminalProps) {
  useSignals()
  const lineIndex = useSignal(0)
  const charIndex = useSignal(0)
  const onCompleteRef = useRef(onComplete)
  onCompleteRef.current = onComplete

  useSignalEffect(() => {
    if (lines.length === 0) return
    let rafId: number
    function tick() {
      const li = lineIndex.value
      const ci = charIndex.value
      if (li >= lines.length) {
        onCompleteRef.current?.()
        if (loop) {
          lineIndex.value = 0
          charIndex.value = 0
        } else {
          return
        }
      } else {
        const target = lines[li]!.text
        if (ci < target.length) {
          charIndex.value = ci + speed
        } else {
          lineIndex.value = li + 1
          charIndex.value = 0
        }
      }
      rafId = requestAnimationFrame(tick)
    }
    rafId = requestAnimationFrame(tick)
    return () => cancelAnimationFrame(rafId)
  })

  const renderedLines = lines.slice(0, lineIndex.value + 1).map((line, i) => {
    const isCurrentLine = i === lineIndex.value
    const text = isCurrentLine ? line.text.slice(0, charIndex.value) : line.text
    return (
      <div key={i} className={styles['line']} data-type={line.type ?? 'output'}>
        {line.prefix && <span className={styles['prefix']}>{line.prefix}</span>}
        <span className={styles['text']}>{text}</span>
        {isCurrentLine && lineIndex.value < lines.length && <span className={styles['cursor']} />}
      </div>
    )
  })

  return (
    <div
      role="group"
      aria-label={labels?.label ?? t(builtin.terminal.label)}
      className={cn(styles['root'], className)}
    >
      {/* Screen readers get the whole script once, in order, from the first render. The
          typing animation is visual only: as a live region it fed them fragments. */}
      <VisuallyHidden>
        {lines.map((line, i) => (
          <span key={i}>
            {line.prefix ? `${line.prefix} ` : ''}
            {line.text}
            {'\n'}
          </span>
        ))}
      </VisuallyHidden>
      <div aria-hidden="true">{renderedLines}</div>
    </div>
  )
}

@layer cascivo.component {
  .root {
    padding: var(--cascivo-space-4);
    overflow-x: auto;
    border: 1px solid var(--cascivo-editor-border, var(--cascivo-color-border));
    border-radius: var(--cascivo-radius-surface);
    background-color: var(--cascivo-terminal-bg, var(--cascivo-editor-bg));
    color: var(--cascivo-terminal-fg, var(--cascivo-editor-fg));
    font-family: var(--cascivo-font-mono);
    font-size: var(--cascivo-text-sm);
    line-height: var(--cascivo-leading-relaxed);
  }

  .line {
    display: flex;
    gap: var(--cascivo-space-2);
  }

  .prefix {
    color: var(--cascivo-editor-syntax-string);
    user-select: none;
  }

  .text {
    flex: 1;
    white-space: pre-wrap;

    [data-type='command'] > & {
      color: var(--cascivo-editor-syntax-keyword);
    }

    [data-type='error'] > & {
      color: var(--cascivo-color-destructive);
    }

    [data-type='comment'] > & {
      color: var(--cascivo-editor-syntax-comment);
    }
  }

  .cursor {
    display: inline-block;
    inline-size: 0.5rem;
    block-size: 1em;
    background-color: currentColor;
  }

  /* Decorative loop — opt-in, so a user who expresses no preference gets no motion. */
  @media (prefers-reduced-motion: no-preference) {
    .cursor {
      animation: global(cascivo-blink) var(--cascivo-duration-loop-fast) step-end infinite;
    }
  }
}

@media (forced-colors: active) {
  .root {
    border-color: CanvasText;
  }

  .prefix,
  .text {
    color: CanvasText;
  }
}
